    /**
     * Ed25519 pubkey of the signing device, hex-encoded
     */
    public let signerPubkey: String
    /**
     * Ed25519 signature over entry_hash, hex-encoded
     */
    public let signature: String
    /**
     * ISO-8601 timestamp
     */
